const newConfig = DashKit.setItem({
  item: {
    type,
    namespace: 'default',
    data: createWidgetData(type),
    layout: {h: itemLayout.h, w: itemLayout.w, x: itemLayout.x, y: itemLayout.y},
  },
  config,
  options: {updateLayout: dropProps.newLayout},
});
```

